//! HTTP resources rendering.
use super::*;

pub(crate) fn render_lib() -> &'static str {
    "// Generated by Poolster Codegen. Do not edit.\n\npub mod client;\npub mod models;\npub mod transport;\n\npub use client::*;\n#[allow(unused_imports)]\npub use models::*;\n"
}

pub(crate) fn resource_client_enabled(options: &RenderOptions) -> bool {
    matches!(options.client_style, SdkClientStyle::Namespaced)
}

pub(crate) fn render_resource_operation(
    method: &str,
    operation: &Operation,
    options: &RenderOptions,
) -> String {
    let direct = direct_method_name(operation, options);
    let response = operation_response_type(operation);
    let error = operation_error_name(operation);
    let parameters = if operation_has_parameters(operation) {
        format!(
            ", input: crate::client::operations::{}",
            operation_request_name(operation)
        )
    } else {
        String::new()
    };
    let request_body = request_body_type(operation)
        .map(|request| format!(", body: &{request}"))
        .unwrap_or_default();
    let input = if operation_has_parameters(operation) {
        "input"
    } else {
        ""
    };
    let separator = if operation_has_parameters(operation) && operation.request_body.is_some() {
        ", "
    } else {
        ""
    };
    let body = if operation.request_body.is_some() {
        "body"
    } else {
        ""
    };
    format!(
        "    /// Invokes {} {} through this resource.\n    pub async fn {method}(&self{parameters}{request_body}) -> Result<{response}, {error}> {{\n        self.client.{direct}({input}{separator}{body}).await\n    }}\n\n",
        operation.method.as_str(),
        operation.path,
    )
}

pub(crate) fn render_resource_pagination_operation(
    method: &str,
    operation: &Operation,
    options: &RenderOptions,
) -> String {
    if matches!(rust_pagination(operation), Some(RustPagination::Url { .. }))
        && !operation_has_parameters(operation)
    {
        let direct = direct_method_name(operation, options);
        let response = operation_response_type(operation);
        let error = operation_error_name(operation);
        return format!(
            "    pub fn {method}_pages(&self) -> impl futures_util::Stream<Item=Result<{response},{error}>> {{ self.client.{direct}_pages() }}\n"
        );
    }
    let direct = direct_method_name(operation, options);
    let request = operation_request_name(operation);
    let response = operation_response_type(operation);
    let error = operation_error_name(operation);
    format!(
        "    /// Lazily fetches all pages through this resource client.\n    pub fn {method}_pages(&self, input: {request}) -> impl futures_util::Stream<Item = Result<{response}, {error}>> {{\n        self.client.{direct}_pages(input)\n    }}\n\n"
    )
}

pub(crate) fn resource_operations(api: &Api) -> BTreeMap<String, Vec<&Operation>> {
    let mut resources = BTreeMap::<String, Vec<&Operation>>::new();
    for operation in &api.operations {
        resources
            .entry(resource_name(operation))
            .or_default()
            .push(operation);
    }
    resources
}

pub(crate) fn resource_name(operation: &Operation) -> String {
    operation
        .annotations
        .get("tags")
        .and_then(serde_json::Value::as_array)
        .and_then(|tags| tags.first())
        .and_then(serde_json::Value::as_str)
        .filter(|tag| !tag.trim().is_empty())
        .map(rust_field_name)
        .or_else(|| {
            operation
                .path
                .split('/')
                .filter(|segment| !segment.is_empty() && !segment.starts_with('{'))
                .find(|segment| {
                    !matches!(*segment, "api" | "email") && !is_version_segment(segment)
                })
                .map(rust_field_name)
        })
        .unwrap_or_else(|| "api".into())
        .trim_start_matches("r#")
        .to_owned()
}

pub(crate) fn is_version_segment(segment: &str) -> bool {
    let mut characters = segment.chars();
    matches!(characters.next(), Some('v' | 'V'))
        && characters
            .next()
            .is_some_and(|character| character.is_ascii_digit())
}

pub(crate) fn resource_accessor_name(resource: &str, direct_methods: &[String]) -> String {
    if direct_methods.iter().any(|method| method == resource) {
        format!("{resource}_resource")
    } else {
        rust_field_name(resource)
    }
}

pub(crate) fn resource_method_name(direct: &str, resource: &str) -> String {
    let singular = resource.strip_suffix('s').unwrap_or(resource);
    let method = direct
        .strip_suffix(resource)
        .or_else(|| direct.strip_suffix(singular))
        .or_else(|| direct.strip_prefix(resource))
        .map(|method| method.trim_matches('_'))
        .filter(|method| !method.is_empty())
        .unwrap_or(direct);
    if method.starts_with("r#") {
        method.into()
    } else {
        rust_field_name(method)
    }
}
